Running command: pip -q install openpyxl >/dev/null 2>&1 || python3 -m pip -q install openpyxl >/dev/null 2>&1; python3 - << 'PY'
import sys, zipfile, io, re
p='/workspace/expenses.xlsx'
# Try openpyxl first
try:
    from openpyxl import load_workbook
    wb=load_workbook(p, data_only=True)
    total=0
    records=[]
    for ws in wb.worksheets:
        for row in ws.iter_rows(min_row=1, values_only=True):
            if not row: continue
            # Try detect header
            if isinstance(row[0], str) and 'date' in row[0].lower():
                continue
            # Expect columns: Date, Description, Amount, Category, Employee
            # Find amount as first numeric in row
            amt=None
            for c in row:
                if isinstance(c,(int,float)):
                    amt=float(c)
                    break
            if amt is None: continue
            # Try employee in row
            emp=None
            for c in row:
                if isinstance(c,str) and c.strip():
                    if c.lower() in ('chen','sarah','john','mary','alex','emma') or 'chen' in c.lower():
                        emp=c
                        break
            records.append((emp,amt,row))
            total+=amt
    print('TOTAL', total)
    print('RECORDS', len(records))
    print('\n'.join(str(r) for r in records[:20]))
except Exception as e:
    print('openpyxl failed:', e)
    # Fallback: try to unzip and read sharedStrings
    try:
        z=zipfile.ZipFile(p)
        names=z.namelist()
        print('ZIP entries:', len(names))
        for n in names:
            if n.endswith('.xml'):
                data=z.read(n)
                if len(data)>0:
                    print(n, len(data))
    except Exception as e2:
        print('zip read failed:', e2)
